// Claude Code workflow that generated data/llm_corpus/. Run it with the Workflow tool,
// passing args {"dir": "<absolute path of this directory>"}.
// The published corpus was generated by this script with file paths that pointed at a scratch directory;
// the prompt text was otherwise identical.
export const meta = {
  name: 'rfc-slop-corpus',
  description: 'Generate 360 topic-matched PEP/RFC-style docs from Opus, Sonnet and Haiku',
  phases: [{ title: 'Generate', detail: '3 models x 12 batches x 10 docs' }],
}
const DIR = args.dir
const MODELS = ['opus', 'sonnet', 'haiku']
const SCHEMA = { type: 'object', properties: { written: { type: 'array', items: { type: 'string' } } }, required: ['written'] }
const jobs = []
for (const m of MODELS) for (let b = 0; b < 12; b++) jobs.push({ m, b })
phase('Generate')
const res = await parallel(jobs.map(({ m, b }) => () => {
  const batch = `${DIR}/data/batches/batch_${String(b).padStart(2, '0')}.md`
  const prompt = `You are generating data for a writing-style study. Read the file ${batch}. It lists 10 items, each with an id, a document type, a title and an abstract.

For each item, write the full document (approximately 1200-1500 words) based on the title and abstract, the way you normally would if a user asked you to write that PEP or RFC with no further instructions. Only output the document text, with no commentary before or after.

Rules:
- The batch file is the ONLY file you may read. Do not read any other file, repository, or web page, do not run searches, and do not invoke any skills (no Skill tool). Write from your own knowledge.
- If you recognize the real document, do not try to reproduce it; write your own version.
- Save each document with the Write tool to ${DIR}/data/llm_corpus/${m}/<id>.md (use the item's id exactly as the filename stem). The file contains only the document, in Markdown.

Return the list of ids you wrote.`
  return agent(prompt, { label: `${m} batch ${b}`, phase: 'Generate', model: m, schema: SCHEMA })
}))
const written = res.filter(Boolean).flatMap(r => r.written)
log(`${written.length} documents reported written; ${res.filter(r => !r).length} agents failed`)
return { written: written.length, failed: jobs.filter((j, i) => !res[i]).map(j => `${j.m}:${j.b}`) }
